export type OfferbookPluginPdas = {
  eventAuthority: typeof findEventAuthorityPda;
  loanVault: typeof findLoanVaultPda;
  offer: typeof findOfferPda;
  signerUser: typeof findSignerUserPda;
  loan: typeof findLoanPda;
  config: typeof findConfigPda;
  feeAuthority: typeof findFeeAuthorityPda;
};

export type OfferbookPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function offerbookProgram() {
  return <T extends OfferbookPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { offerbook: OfferbookPlugin }> => {
    return extendClient(client, {
      offerbook: <OfferbookPlugin>{
        accounts: {
          baseAssetV1: addSelfFetchFunctions(client, getBaseAssetV1Codec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          loan: addSelfFetchFunctions(client, getLoanCodec()),
          offer: addSelfFetchFunctions(client, getOfferCodec()),
          user: addSelfFetchFunctions(client, getUserCodec()),
        },
        instructions: {
          cancelOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelOfferInstructionAsync(input),
            ),
          claimFee: (input) =>
            addSelfPlanAndSendFunctions(client, getClaimFeeInstruction(input)),
          claimNonFungibleLoan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimNonFungibleLoanInstructionAsync(input),
            ),
          claimTokenLoan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimTokenLoanInstructionAsync(input),
            ),
          createNftCollateralOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateNftCollateralOfferInstructionAsync(input),
            ),
          createNftPrincipalOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateNftPrincipalOfferInstructionAsync(input),
            ),
          createTokenCollateralOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateTokenCollateralOfferInstructionAsync(input),
            ),
          createTokenPrincipalOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateTokenPrincipalOfferInstructionAsync(input),
            ),
          createUser: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateUserInstructionAsync(input),
            ),
          escrowClassicNftDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEscrowClassicNftDepositInstructionAsync(input),
            ),
          escrowClassicNftWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEscrowClassicNftWithdrawInstructionAsync(input),
            ),
          escrowCoreNftDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEscrowCoreNftDepositInstructionAsync(input),
            ),
          escrowCoreNftWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEscrowCoreNftWithdrawInstructionAsync(input),
            ),
          escrowProgrammableNftDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEscrowProgrammableNftDepositInstructionAsync(input),
            ),
          escrowProgrammableNftWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEscrowProgrammableNftWithdrawInstructionAsync(input),
            ),
          escrowTokenDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEscrowTokenDepositInstructionAsync(input),
            ),
          escrowTokenWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEscrowTokenWithdrawInstructionAsync(input),
            ),
          extendLoan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExtendLoanInstructionAsync(input),
            ),
          fillNonFungibleCollateralOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillNonFungibleCollateralOfferInstructionAsync(input),
            ),
          fillNonFungiblePrincipalOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillNonFungiblePrincipalOfferInstructionAsync(input),
            ),
          fillTokenCollateralOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillTokenCollateralOfferInstructionAsync(input),
            ),
          fillTokenPrincipalOffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillTokenPrincipalOfferInstructionAsync(input),
            ),
          init: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          repayNonFungibleLoan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRepayNonFungibleLoanInstructionAsync(input),
            ),
          repayTokenLoan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRepayTokenLoanInstructionAsync(input),
            ),
          setLoanExtendable: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetLoanExtendableInstructionAsync(input),
            ),
          updateConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateConfigInstruction(input),
            ),
        },
        pdas: {
          eventAuthority: findEventAuthorityPda,
          loanVault: findLoanVaultPda,
          offer: findOfferPda,
          signerUser: findSignerUserPda,
          loan: findLoanPda,
          config: findConfigPda,
          feeAuthority: findFeeAuthorityPda,
        },
        identifyAccount: identifyOfferbookAccount,
        identifyInstruction: identifyOfferbookInstruction,
        parseInstruction: parseOfferbookInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
